use vstd::prelude::*;

verus! {
    fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
        requires
            a.len() <= u32::MAX as usize, // Ensure the length of the input vector is within bounds
        ensures
            result.len() == a.len(), // The output vector's length matches the input vector's length
            forall|i: nat| 0 <= i < result.len() ==> result[i] == 1, // All elements in the output vector are 1
    {
        let mut result: Vec<i32> = Vec::new(); // Initialize the output vector
        let len = a.len() as nat; // Get the length of the input vector
        result.resize(len as usize, 0); // Resize the output vector to the same length as input

        let mut idx: nat = 0; // Initialize the loop counter
        while idx < len
            invariant
                idx <= len, // Loop counter is within bounds
                result.len() == idx as usize, // Current output length equals the number of iterations completed
                forall|j: nat| 0 <= j < idx ==> result[j] == 1, // All elements written so far are 1
            decreases len - idx, // Decrease clause for termination
        {
            result[idx as usize] = 1; // Set the current index in the output vector to 1
            idx = idx + 1; // Increment the loop counter
        }
        result // Return the constructed output vector
    }
}
